def pair(s):
    a,b=s.split('~',1);return a.strip(),b.strip()

def yaml_lines(obj,depth=0):
    result=[];pad=' '*depth
    if isinstance(obj,dict):
        for k,v in obj.items():
            if isinstance(v,(list,dict)):
                result.append(pad+k+':');result.extend(yaml_lines(v,depth+2))
            else:result.append(pad+k+': '+json.dumps(v,ensure_ascii=False))
    else:
        for v in obj:
            if isinstance(v,dict):
                first=next(iter(v));result.append(pad+'- '+first+': '+json.dumps(v[first],ensure_ascii=False))
                result.extend(yaml_lines({k:x for k,x in v.items() if k!=first},depth+2))
            else:result.append(pad+'- '+json.dumps(v,ensure_ascii=False))
    return result

if __name__=='__main__':
    lines=[line for block in (PHYSICS,CHEMISTRY) for line in block.splitlines() if line.strip()]
    assert len(lines)==50
    slugs=set()
    for line in lines:
        parts=line.split('|');assert len(parts)==13,(parts[0],len(parts))
        slug,subject,title,theory,apparatus,method,columns,calculation,precaution,error,viva,answer,incorrect=parts
        assert slug not in slugs;slugs.add(slug)
        title_en,title_bn=pair(title);theory_en,theory_bn=pair(theory)
        method_en,method_bn=pair(method);calc_en,calc_bn=pair(calculation)
        safe_en,safe_bn=pair(precaution);error_en,error_bn=pair(error)
        q_en,q_bn=pair(viva);a_en,a_bn=pair(answer)
        apparatus_pairs=[pair(a.replace(':','~',1)) for a in apparatus.split(';')]
        headers=columns.split(';');assert len(headers)>=4,(slug,headers)
        lab_path=ROOT/subject/'honours'/f'{slug}.mdx'
        quiz_path=ROOT/'quizzes'/f'honours-{slug}.json'
        assert not lab_path.exists() and not quiz_path.exists(),f'Existing topic {slug}'
        introduction_en='Check the equipment calibration and record units, zero readings and ambient conditions before starting.'
        introduction_bn='শুরুর আগে যন্ত্রের ক্রমাঙ্কন দেখে একক, শূন্য পাঠ ও পরিবেশের অবস্থা লিখুন।'
        finish_en='Repeat at least three independent trials, preserve raw readings, compute the result with units and compare the observed trend against the stated model.'
        finish_bn='অন্তত তিনটি স্বাধীন পাঠ নিন, কাঁচা পাঠ রাখুন, এককসহ ফল বের করে বর্ণিত মডেলের সঙ্গে প্রবণতা তুলনা করুন।'
        data=dict(type='experiment',slug=slug,title_bn=title_bn,title_en=title_en,subject=subject,level='honours',aim='Determine or verify: '+title_en+'. Record observations and compare against the stated model.',aim_bn='উদ্দেশ্য: '+title_bn+'; পর্যবেক্ষণ লিখে তাত্ত্বিক মডেলের সঙ্গে তুলনা।',apparatus=[en for en,bn in apparatus_pairs],apparatus_bn=[bn for en,bn in apparatus_pairs],theory=theory_en,theory_bn=theory_bn,procedure=[introduction_en,method_en,finish_en],procedure_bn=[introduction_bn,method_bn,finish_bn],observation_table=dict(headers=headers,rows=[['record']*len(headers) for _ in range(3)]),calculation=calc_en,calculation_bn=calc_bn,precautions=[safe_en],precautions_bn=[safe_bn],sources_of_error=[error_en],sources_of_error_bn=[error_bn],viva=[dict(q=q_en,a=a_en,q_bn=q_bn,a_bn=a_bn)],tags=['honours',subject,'laboratory','supervised practical'])
        lab_path.write_text('---\n'+'\n'.join(yaml_lines(data))+'\n---\n\n**Report / প্রতিপাদন:** Preserve raw readings, graph where specified, state the model assumptions, final value, units and likely systematic error. Never invent data.\n\n**ব্যবহারিক সতর্কতা:** শিক্ষকের তত্ত্বাবধান ও প্রতিষ্ঠানের রাসায়নিক/বৈদ্যুতিক বর্জ্যবিধি মেনে চলুন।\n')
        wrong=incorrect.split(';');assert len(wrong)==3 and len(set([a_en]+wrong))==4,(slug,wrong)
        quiz=dict(slug='honours-'+slug,title_en=title_en+' — lab viva',title_bn=title_bn+' — ব্যবহারিক প্রশ্ন',subject=subject,level='honours',chapter='Honours practical',chapter_bn='স্নাতক ব্যবহারিক',description_en='Concept check after the practical.',description_bn='পরীক্ষার পর ধারণা যাচাই।',questions=[dict(q=q_en,q_bn=q_bn,options=[a_en]+wrong,options_bn=[a_bn]+wrong,answer=0,explanation=a_en+' '+theory_en,explanation_bn=a_bn+' '+theory_bn)])
        quiz_path.write_text(json.dumps(quiz,ensure_ascii=False,indent=2)+'\n')
    print('Added',len(lines),'bilingual practicals and lab-viva quizzes.')
